from dataclasses import dataclass

FREE_SHIPPING_OVER_DOLLARS = 50


@dataclass
class Cart:
    subtotal_cents: int
    member: bool


def shipping_cents(cart: Cart) -> int:
    """Members ship free; everyone else ships free over $50."""
    if cart.member or cart.subtotal_cents >= FREE_SHIPPING_OVER_DOLLARS:
        return 0
    return 599
